L(s,[('c1','Consist of several thousand radio cells, each with a coverage area of between 500 m to 35 km radius.','کئی ہزار ریڈیو سیلز پر مشتمل ہوتے ہیں، ہر ایک کا کوریج علاقہ ۵۰۰ میٹر سے ۳۵ کلومیٹر رداس کے درمیان ہوتا ہے۔','څو زره راډیو حجرو لري، هره یوه د ۵۰۰ مترو نه تر ۳۵ کیلومتره شعاع پورې د پوښښ سیمه لري.'),('c2','Comprised of several access networks and a single core network.','کئی ایکسیس نیٹ ورکس اور ایک واحد کور نیٹ ورک پر مشتمل ہوتے ہیں۔','له څو لاسرسي شبکو او یوې واحدې مرکزي شبکې جوړ دي.'),('c3','Usually cover an entire country and serve millions of subscribers.','عموماً پورے ملک کا احاطہ کرتے ہیں اور لاکھوں صارفین کو خدمت فراہم کرتے ہیں۔','معمولاً ټول هېواد پوښي او ملیونونو ګډونوالو ته خدمت کوي.'),('c4','Initially designed for speech telephony, but increasingly used for data transmission.','ابتدائی طور پر آواز کی ٹیلی فونی کے لیے بنائے گئے لیکن اب ڈیٹا ترسیل کے لیے بھی بڑھتے ہوئے استعمال ہو رہے ہیں۔','په پیل کې د وینا تلیفون لپاره ډیزاین شوي، خو د ډېټا د لېږد لپاره هم په زیاتېدونکي ډول کارول کېږي.'),('c5','Support of terminal and personal mobility.','ٹرمینل اور ذاتی نقل پذیری کی حمایت کرتے ہیں۔','د ټرمینل او شخصي خوځښت ملاتړ کوي.'),('c6','Examples: GSM and CDMA','مثالیں: جی ایس ایم اور سی ڈی ایم اے','بېلګې: GSM او CDMA')],'cc')
H(s,'h2','6.3.2 Global Positioning System (GPS)','۶.۳.۲ گلوبل پوزیشننگ سسٹم (جی پی ایس)','۶.۳.۲ نړیوال موقعیت سیسټم (GPS)')
add(s,'a','The Global Positioning System (GPS) is a satellite-based navigation system. The GPS system consists of 24 satellites, constructed and operated by the U.S. Department of Defense. It is used for land, sea and air navigation to provide time and locations for vehicles and ships. GPS works in any weather conditions, anywhere in the world, 24 hours a day. There are no subscription fees or setup charges to use GPS. The 24 satellites are moving around the Earth about 12,000 miles above the Earth surface. They are constantly moving, making two complete orbits in less than 24 hours. These satellites are traveling at speeds of roughly 7,000 miles an hour. GPS satellites are powered by solar energy. They have backup batteries onboard to keep them running, when there is no solar power.','گلوبل پوزیشننگ سسٹم (جی پی ایس) سیٹلائٹ پر مبنی نیویگیشن سسٹم ہے۔ جی پی ایس سسٹم ۲۴ سیٹلائٹس پر مشتمل ہے جنہیں امریکی محکمہ دفاع نے بنایا اور چلایا ہے۔ یہ زمینی، سمندری اور فضائی نیویگیشن کے لیے استعمال ہوتا ہے تاکہ گاڑیوں اور جہازوں کو وقت اور مقامات فراہم کیے جا سکیں۔ جی پی ایس دنیا میں کہیں بھی، دن کے ۲۴ گھنٹے، کسی بھی موسمی حالت میں کام کرتا ہے۔ جی پی ایس استعمال کرنے کے لیے کوئی سبسکرپشن فیس یا سیٹ اپ چارجز نہیں ہیں۔ ۲۴ سیٹلائٹس زمین کی سطح سے تقریباً ۱۲،۰۰۰ میل اوپر زمین کے گرد گھوم رہے ہیں۔ وہ مسلسل حرکت میں ہیں اور ۲۴ گھنٹے سے کم وقت میں دو مکمل چکر لگاتے ہیں۔ یہ سیٹلائٹس تقریباً ۷،۰۰۰ میل فی گھنٹہ کی رفتار سے سفر کرتے ہیں۔ جی پی ایس سیٹلائٹس شمسی توانائی سے چلتے ہیں۔ ان میں بیک اپ بیٹریاں بھی نصب ہیں جو شمسی توانائی نہ ہونے پر انہیں چلتا رکھتی ہیں۔','نړیوال موقعیت سیسټم (GPS) یو سپوږمکۍ پر بنسټ د لارښوونې سیسټم دی. د GPS سیسټم له ۲۴ سپوږمکیو جوړ دی چې د متحده ایالاتو د دفاع وزارت لخوا جوړې او چالېږي. دا د ځمکې، سمندر او هوا د لارښوونې لپاره کارول کېږي ترڅو موټرو او بېړیو ته وخت او موقعیتونه برابر کړي. GPS په هر ډول موسمي حالت کې، په نړۍ کې هر ځای، په ورځ ۲۴ ساعته کار کوي. د GPS د کارولو لپاره هېڅ د ګډون فیس یا د جوړولو لګښتونه نشته. ۲۴ سپوږمکۍ د ځمکې د مخ نه نژدې ۱۲،۰۰۰ مایله پورته د ځمکې شاوخوا ګرځي. دوی په دوامداره ډول حرکت کوي او په ۲۴ ساعتونو کې دوه بشپړ مدارونه بشپړوي. دا سپوږمکۍ تقریباً ۷،۰۰۰ مایله په ساعت ګړندیتوب سفر کوي. د GPS سپوږمکۍ په لمریزې انرژۍ چالېږي. دوی په بورډ د بیک اپ بیټرۍ لري ترڅو هغه چالان وساتي کله چې لمریزه انرژي نه وي.')
def gps():
    b='<circle cx="140" cy="115" r="60" fill="#2a4a9a" stroke="#111"/><ellipse cx="140" cy="115" rx="50" ry="25" fill="#6a9a4a" opacity=".6"/>'
    for (rx,ry,rot) in [(120,40,0),(120,40,60),(120,40,120)]:
        b+=f'<ellipse cx="140" cy="115" rx="{rx}" ry="{ry}" fill="none" stroke="#555" transform="rotate({rot} 140 115)"/>'
    import math
    for k in range(12):
        a=k*math.pi/6
        b+=f'<rect x="{140+105*math.cos(a)-4:.0f}" y="{115+85*math.sin(a)-4:.0f}" width="8" height="8" fill="#222"/>'
    return svg(280,230,'GPS satellite orbits: satellites in several orbits around the Earth',b)
s['figures']=[dict(svg=gps(),id='cs11-s199-fig1',caption='Figure 6.6 GPS satellite orbits',captionUrdu='شکل ۶.۶ جی پی ایس سیٹلائٹ کے مدار',captionPashto='انځور ۶.۶ د GPS سپوږمکیو مدارونه',labels=[])]
F.fg(0)
F.done()
fin(s,'Printed page 190: “Characteristics of Cellular networks” with six bullets, the banner “6.3.2 Global Positioning System (GPS)” with its paragraph (printed wrapped around the figure) and Figure 6.6 GPS satellite orbits (a picture of the Earth with satellites in several orbits; redrawn as a simple coded SVG).')
